import building_with_claude.prompt_evaluation_and_engineering as pe

test_case = {
    "task": "Write a Python function that takes a list of EC2 instance dictionaries and returns only the instances that are in 'running' state and have a tag named 'Environment' with value 'production'",
    "format": "python",
}

output = "Here's a Python function that filters EC2 instances based on state and tags:\n\n```python\ndef filter_production_running_instances(instances):\n    \"\"\"\n    Filter EC2 instances that are running and tagged as production environment.\n    \n    Args:\n        instances: List of EC2 instance dictionaries\n        \n    Returns:\n        List of instances that are in 'running' state and have \n        Environment tag set to 'production'\n    \"\"\"\n    filtered_instances = []\n    \n    for instance in instances:\n        # Check if instance is in running state\n        if instance.get('State', {}).get('Name') != 'running':\n            continue\n            \n        # Check for Environment=production tag\n        tags = instance.get('Tags', [])\n        has_production_tag = False\n        \n        for tag in tags:\n            if tag.get('Key') == 'Environment' and tag.get('Value') == 'production':\n                has_production_tag = True\n                break\n        \n        if has_production_tag:\n            filtered_instances.append(instance)\n    \n    return filtered_instances\n```\n\n**Alternative implementation using list comprehension:**\n\n```python\ndef filter_production_running_instances(instances):\n    \"\"\"\n    Filter EC2 instances that are running and tagged as production environment.\n    \"\"\"\n    def is_production_running(instance):\n        # Check running state\n        is_running = instance.get('State', {}).get('Name') == 'running'\n        \n        # Check for production tag\n        tags = instance.get('Tags', [])\n        is_production = any(\n            tag.get('Key') == 'Environment' and tag.get('Value') == 'production'\n            for tag in tags\n        )\n        \n        return is_running and is_production\n    \n    return [instance for instance in instances if is_production_running(instance)]\n```\n\n**Example usage:**\n\n```python\n# Sample EC2 instances data\ninstances = [\n    {\n        'InstanceId': 'i-1234567890abcdef0',\n        'State': {'Name': 'running'},\n        'Tags': [\n            {'Key': 'Environment', 'Value': 'production'},\n            {'Key': 'Name', 'Value': 'WebServer1'}\n        ]\n    },\n    {\n        'InstanceId': 'i-1234567890abcdef1',\n        'State': {'Name': 'stopped'},\n        'Tags': [\n            {'Key': 'Environment', 'Value': 'production'}\n        ]\n    },\n    {\n        'InstanceId': 'i-1234567890abcdef2',\n        'State': {'Name': 'running'},\n        'Tags': [\n            {'Key': 'Environment', 'Value': 'development'}\n        ]\n    },\n    {\n        'InstanceId': 'i-1234567890abcdef3',\n        'State': {'Name': 'running'},\n        'Tags': [\n            {'Key': 'Environment', 'Value': 'production'},\n            {'Key': 'Name', 'Value': 'AppServer1'}\n        ]\n    }\n]\n\n# Filter instances\nresult = filter_production_running_instances(instances)\n\n# Print results\nfor instance in result:\n    print(f\"Instance ID: {instance['InstanceId']}\")\n```\n\nThis will return only instances with IDs `i-1234567890abcdef0` and `i-1234567890abcdef3` since they are both running and have the Environment=production tag."

model_grade = pe.grade_by_model(test_case, output)
print(f"model_grade: {model_grade}")
model_score = model_grade["score"]
print(f"model_score: {model_score}")
syntax_score = pe.grade_syntax(output, test_case)
print(f"syntax_score: {syntax_score}")
score = (model_score + syntax_score) / 2
print(f"score: {score}")
